"use client";

import { useMemo } from "react";
import {
  readApiResource,
  useApiResource,
  type ApiResourceAdapter,
} from "./use-api-resource";

export type TokenMetadata = {
  mint: string;
  name: string;
  symbol: string;
  icon: string | null;
  decimals: number;
  isVerified: boolean | null;
  tags: string[];
  liquidity: number | null;
  holderCount: number | null;
};

export type TokenMetadataAdapter = ApiResourceAdapter<
  { mint: string },
  TokenMetadata
>;

export function createTokenMetadataAdapter(
  endpoint = "/api/token-metadata",
): TokenMetadataAdapter {
  return async ({ mint }, { signal }) => {
    const url = new URL(endpoint, window.location.origin);
    url.searchParams.set("mint", mint);
    return readApiResource<TokenMetadata>(await fetch(url, { signal }));
  };
}

export function useTokenMetadata(
  mint: string | null | undefined,
  options: {
    adapter?: TokenMetadataAdapter;
    endpoint?: string;
    enabled?: boolean;
  } = {},
) {
  const normalizedMint = mint?.trim() ?? "";
  const defaultAdapter = useMemo(
    () => createTokenMetadataAdapter(options.endpoint),
    [options.endpoint],
  );

  return useApiResource({
    adapter: options.adapter ?? defaultAdapter,
    enabled: (options.enabled ?? true) && normalizedMint.length > 0,
    input: { mint: normalizedMint },
    requestKey: normalizedMint,
  });
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

export type ApiResourceStatus = "idle" | "loading" | "success" | "error";

export type ApiResourceError = {
  code: string;
  message: string;
  retryable: boolean;
  status?: number;
};

export type ApiResourceAdapter<Input, Data> = (
  input: Input,
  context: { signal: AbortSignal },
) => Promise<Data>;

export type ApiResourceState<Data> = {
  status: ApiResourceStatus;
  data: Data | null;
  error: ApiResourceError | null;
  updatedAt: string | null;
};

type ApiEnvelope<Data> = {
  data?: Data;
  error?: Partial<ApiResourceError> & { message?: string };
};

export class ApiResourceRequestError extends Error {
  code: string;
  retryable: boolean;
  status?: number;

  constructor(error: ApiResourceError) {
    super(error.message);
    this.name = "ApiResourceRequestError";
    this.code = error.code;
    this.retryable = error.retryable;
    this.status = error.status;
  }
}

export async function readApiResource<Data>(response: Response) {
  let body: ApiEnvelope<Data>;

  try {
    body = (await response.json()) as ApiEnvelope<Data>;
  } catch {
    throw new ApiResourceRequestError({
      code: "INVALID_RESPONSE",
      message: "The provider returned an unreadable response.",
      retryable: true,
      status: response.status,
    });
  }

  if (!response.ok || body.error || body.data === undefined) {
    throw new ApiResourceRequestError({
      code: body.error?.code || "REQUEST_FAILED",
      message: body.error?.message || "The provider request failed.",
      retryable: body.error?.retryable ?? response.status >= 500,
      status: response.status,
    });
  }

  return body.data;
}

function normalizeError(cause: unknown): ApiResourceError {
  if (cause instanceof ApiResourceRequestError) {
    return {
      code: cause.code,
      message: cause.message,
      retryable: cause.retryable,
      status: cause.status,
    };
  }

  return {
    code: "UNKNOWN_ERROR",
    message: cause instanceof Error ? cause.message : "The request failed.",
    retryable: true,
  };
}

export function useApiResource<Input, Data>({
  adapter,
  enabled,
  input,
  requestKey,
}: {
  adapter: ApiResourceAdapter<Input, Data>;
  enabled: boolean;
  input: Input;
  requestKey: string;
}) {
  const inputRef = useRef(input);
  const requestIdRef = useRef(0);
  const [refreshKey, setRefreshKey] = useState(0);
  const [state, setState] = useState<ApiResourceState<Data>>({
    status: "idle",
    data: null,
    error: null,
    updatedAt: null,
  });

  useEffect(() => {
    inputRef.current = input;
  }, [input]);

  useEffect(() => {
    if (!enabled) return;

    const requestId = ++requestIdRef.current;
    const controller = new AbortController();
    const loadingTimer = window.setTimeout(() => {
      setState((current) => ({
        ...current,
        status: "loading",
        error: null,
      }));
    }, 0);

    void adapter(inputRef.current, { signal: controller.signal })
      .then((data) => {
        window.clearTimeout(loadingTimer);
        if (controller.signal.aborted || requestId !== requestIdRef.current) {
          return;
        }
        setState({
          status: "success",
          data,
          error: null,
          updatedAt: new Date().toISOString(),
        });
      })
      .catch((cause: unknown) => {
        window.clearTimeout(loadingTimer);
        if (controller.signal.aborted || requestId !== requestIdRef.current) {
          return;
        }
        setState((current) => ({
          ...current,
          status: "error",
          error: normalizeError(cause),
        }));
      });

    return () => {
      window.clearTimeout(loadingTimer);
      controller.abort();
    };
  }, [adapter, enabled, refreshKey, requestKey]);

  const refetch = useCallback(() => setRefreshKey((value) => value + 1), []);
  const visibleState: ApiResourceState<Data> = enabled
    ? state
    : { status: "idle", data: null, error: null, updatedAt: null };

  return {
    ...visibleState,
    isIdle: visibleState.status === "idle",
    isLoading: visibleState.status === "loading",
    isSuccess: visibleState.status === "success",
    isError: visibleState.status === "error",
    refetch,
  };
}

import { NextResponse } from "next/server";

export const runtime = "nodejs";

type JupiterToken = Record<string, unknown>;
const JUPITER_TOKENS_URL = "https://api.jup.ag/tokens/v2/search";
const BASE58_PUBLIC_KEY = /^[1-9A-HJ-NP-Za-km-z]{32,44}$/;

function jsonError(code: string, message: string, status: number, retryable = false) {
  return NextResponse.json({ error: { code, message, retryable } }, { status });
}

function optionalNumber(value: unknown) {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function normalizeToken(token: JupiterToken) {
  return {
    mint: token.id,
    name: typeof token.name === "string" ? token.name : "Unknown token",
    symbol: typeof token.symbol === "string" ? token.symbol : "UNKNOWN",
    icon: typeof token.icon === "string" ? token.icon : null,
    decimals:
      typeof token.decimals === "number" && Number.isInteger(token.decimals)
        ? token.decimals
        : 0,
    isVerified: typeof token.isVerified === "boolean" ? token.isVerified : null,
    tags: Array.isArray(token.tags)
      ? token.tags.filter((tag): tag is string => typeof tag === "string")
      : [],
    liquidity: optionalNumber(token.liquidity),
    holderCount: optionalNumber(token.holderCount),
  };
}

export async function GET(request: Request) {
  const mint = new URL(request.url).searchParams.get("mint")?.trim() ?? "";
  const apiKey = process.env.JUPITER_API_KEY;
  if (!BASE58_PUBLIC_KEY.test(mint)) {
    return jsonError("INVALID_MINT", "A valid Solana token mint is required.", 400);
  }
  if (!apiKey) {
    return jsonError("MISSING_CONFIGURATION", "Missing JUPITER_API_KEY.", 500);
  }

  const url = new URL(JUPITER_TOKENS_URL);
  url.searchParams.set("query", mint);

  try {
    const response = await fetch(url, {
      headers: { "x-api-key": apiKey },
      next: { revalidate: 60 },
    });
    if (!response.ok) {
      return jsonError("PROVIDER_ERROR", "The token metadata request failed.", 502, true);
    }
    const payload = (await response.json()) as unknown;
    if (!Array.isArray(payload)) {
      return jsonError("INVALID_PROVIDER_RESPONSE", "The token provider returned invalid data.", 502, true);
    }
    const token = (payload as JupiterToken[]).find((item) => item.id === mint);
    if (!token) return jsonError("TOKEN_NOT_FOUND", "Token metadata was not found.", 404);
    return NextResponse.json({ data: normalizeToken(token) });
  } catch {
    return jsonError("PROVIDER_UNAVAILABLE", "The token provider is unavailable.", 502, true);
  }
}
